import com.navigatemama.core.data.network.dto.PlaceReviewRequest
import com.navigatemama.core.data.network.dto.PlaceReviewResponse
import com.navigatemama.core.data.network.dto.ProfileDto
import com.navigatemama.core.data.network.dto.SafetyCheckResponse
import com.navigatemama.core.data.network.dto.SupportRequestDto
import com.navigatemama.core.data.network.dto.SupportResponseDto
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.UUID
import java.util.concurrent.TimeUnit

class FamilyCompanionRepository(
    private val baseUrl: String = "http://10.0.2.2:8000/api/v1/android/",
    private val defaultFamilyId: String = UUID.randomUUID().toString()
) {
    private val api: FamilyCompanionApi
    private val okHttpClient: OkHttpClient
    private val gson = Gson()

    // In-memory cache for recent responses
    private var cachedProfile: ProfileDto? = null
    private var cachedPlaces: List<PlaceDto>? = null
    private var cachedSafetyCheck: SafetyCheckResponse? = null
    private val chatHistory = mutableListOf<Pair<String, String>>() // user, assistant messages

    init {
        val loggingInterceptor = HttpLoggingInterceptor().apply {
            level = HttpLoggingInterceptor.Level.BODY
        }

        okHttpClient = OkHttpClient.Builder()
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            .addInterceptor(loggingInterceptor)
            .build()

        val retrofit = Retrofit.Builder()
            .baseUrl(baseUrl)
            .client(okHttpClient)
            .addConverterFactory(GsonConverterFactory.create())
            .build()

        api = retrofit.create(FamilyCompanionApi::class.java)
    }

    // ── AI Chat ────────────────────────────────────────────────────

    suspend fun sendChat(
        message: String,
        familyId: String = defaultFamilyId,
        personId: String? = null,
        tone: String = "warm"
    ): Result<ChatResponse> = runCatching {
        val response = withContext(Dispatchers.IO) {
            api.chat(message, familyId, personId, tone)
        }
        chatHistory.add(message to response.message)
        response
    }

    fun sendChatStream(
        message: String,
        familyId: String = defaultFamilyId,
        personId: String? = null,
        tone: String = "warm"
    ): Flow<String> = flow {
        val url = "${baseUrl}chat/stream?" +
                "message=${java.net.URLEncoder.encode(message, "UTF-8")}" +
                "&family_id=${java.net.URLEncoder.encode(familyId, "UTF-8")}" +
                (personId?.let { "&person_id=${java.net.URLEncoder.encode(it, "UTF-8")}" } ?: "") +
                "&tone=${java.net.URLEncoder.encode(tone, "UTF-8")}"

        val request = Request.Builder()
            .url(url)
            .post("".toRequestBody("application/json".toMediaType()))
            .header("Accept", "text/event-stream")
            .build()

        val response = okHttpClient.newCall(request).execute()
        val fullResponse = StringBuilder()

        response.body?.let { body ->
            BufferedReader(InputStreamReader(body.byteStream())).use { reader ->
                var line: String?
                while (reader.readLine().also { line = it } != null) {
                    val currentLine = line ?: continue
                    if (currentLine.startsWith("data: ")) {
                        val data = currentLine.removePrefix("data: ")
                        if (data == "[DONE]") break
                        emit(data)
                        fullResponse.append(data)
                    }
                }
            }
        }

        chatHistory.add(message to fullResponse.toString())
    }.flowOn(Dispatchers.IO)

    fun getChatHistory(): List<Pair<String, String>> = chatHistory.toList()

    fun clearChatHistory() {
        chatHistory.clear()
    }

    // ── Profile ───────────────────────────────────────────────────

    suspend fun getProfile(
        familyId: String = defaultFamilyId,
        personId: String? = null
    ): Result<ProfileDto> = runCatching {
        val profile = withContext(Dispatchers.IO) {
            api.getProfile(familyId, personId)
        }
        cachedProfile = profile
        profile
    }

    fun getCachedProfile(): ProfileDto? = cachedProfile

    // ── Journey ───────────────────────────────────────────────────

    suspend fun createJourneyEntry(entry: JourneyEntryDto): Result<JourneyEntryResponse> =
        runCatching {
            withContext(Dispatchers.IO) { api.createJourneyEntry(entry) }
        }

    suspend fun getJourneyByWeek(
        week: Int,
        personId: String
    ): Result<List<JourneyEntryResponse>> = runCatching {
        withContext(Dispatchers.IO) { api.getJourneyByWeek(week, personId) }
    }

    // ── Health Metrics ────────────────────────────────────────────

    suspend fun createHealthMetric(metric: HealthMetricDto): Result<HealthMetricResponse> =
        runCatching {
            withContext(Dispatchers.IO) { api.createHealthMetric(metric) }
        }

    suspend fun getHealthMetrics(
        personId: String,
        metricType: String? = null,
        limit: Int = 50
    ): Result<List<HealthMetricResponse>> = runCatching {
        withContext(Dispatchers.IO) { api.getHealthMetrics(personId, metricType, limit) }
    }

    // ── Places ────────────────────────────────────────────────────

    suspend fun getPlaces(
        category: String? = null,
        lat: Double? = null,
        lng: Double? = null,
        radiusKm: Double = 10.0,
        limit: Int = 20
    ): Result<List<PlaceDto>> = runCatching {
        val places = withContext(Dispatchers.IO) {
            api.getPlaces(category, lat, lng, radiusKm, limit)
        }
        cachedPlaces = places
        places
    }

    fun getCachedPlaces(): List<PlaceDto>? = cachedPlaces

    suspend fun submitPlaceReview(review: PlaceReviewRequest): Result<PlaceReviewResponse> =
        runCatching {
            withContext(Dispatchers.IO) { api.submitPlaceReview(review) }
        }

    // ── Support ───────────────────────────────────────────────────

    suspend fun submitSupport(request: SupportRequestDto): Result<SupportResponseDto> =
        runCatching {
            withContext(Dispatchers.IO) { api.submitSupport(request) }
        }

    // ── Safety Check ──────────────────────────────────────────────

    suspend fun getSafetyCheck(
        familyId: String = defaultFamilyId
    ): Result<SafetyCheckResponse> = runCatching {
        val safetyCheck = withContext(Dispatchers.IO) {
            api.getSafetyCheck(familyId)
        }
        cachedSafetyCheck = safetyCheck
        safetyCheck
    }

    fun getCachedSafetyCheck(): SafetyCheckResponse? = cachedSafetyCheck
}
