import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.viewModelScope
import com.navigatemama.app.shared.ServiceLocator
import com.navigatemama.core.data.repository.FamilyCompanionRepository
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.launch

data class ChatMessage(
    val text: String,
    val isUser: Boolean,
    val isStreaming: Boolean = false
)

class CompanionViewModel(application: Application) : AndroidViewModel(application) {
    private val repository: FamilyCompanionRepository = ServiceLocator.companionRepository(application)

    private val _messages = MutableLiveData<List<ChatMessage>>(emptyList())
    val messages: LiveData<List<ChatMessage>> = _messages

    private val _isLoading = MutableLiveData(false)
    val isLoading: LiveData<Boolean> = _isLoading

    private val _error = MutableLiveData<String?>(null)
    val error: LiveData<String?> = _error

    private val _currentStreamingText = MutableLiveData<String?>(null)
    val currentStreamingText: LiveData<String?> = _currentStreamingText

    fun sendMessage(text: String) {
        if (text.isBlank()) return

        val current = _messages.value.orEmpty().toMutableList()

        // Add user message
        current.add(ChatMessage(text = text.trim(), isUser = true))
        _messages.value = current
        _error.value = null

        // Start streaming response
        _isLoading.value = true

        viewModelScope.launch {
            val streamBuffer = StringBuilder()

            repository.sendChatStream(message = text.trim())
                .catch { e ->
                    _error.value = "Connection to companion service failed. Check that the backend is running."
                    _isLoading.value = false
                    // Try non-streaming as fallback
                    tryFallbackChat(text.trim(), current)
                }
                .collect { token ->
                    streamBuffer.append(token)
                    _currentStreamingText.value = streamBuffer.toString()
                }

            // Streaming complete — finalize the message
            val finalText = streamBuffer.toString()
            if (finalText.isNotBlank()) {
                val finalList = _messages.value.orEmpty().toMutableList()
                finalList.add(ChatMessage(text = finalText, isUser = false))
                _messages.value = finalList
            }

            _currentStreamingText.value = null
            _isLoading.value = false
        }
    }

    private suspend fun tryFallbackChat(text: String, current: MutableList<ChatMessage>) {
        repository.sendChat(message = text)
            .onSuccess { response ->
                val updated = _messages.value.orEmpty().toMutableList()
                updated.add(ChatMessage(text = response.message, isUser = false))
                _messages.value = updated
            }
            .onFailure { e ->
                val updated = _messages.value.orEmpty().toMutableList()
                updated.add(
                    ChatMessage(
                        text = "I'm here for you, but I'm having trouble connecting right now. " +
                                "Please try again in a moment.",
                        isUser = false
                    )
                )
                _messages.value = updated
            }
    }

    fun clearError() {
        _error.value = null
    }
}
