import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.navigatemama.app.databinding.ItemCompanionMessageUserBinding
import com.navigatemama.app.databinding.ItemCompanionMessageAssistantBinding
import com.navigatemama.app.R

class CompanionAdapter : RecyclerView.Adapter<RecyclerView.ViewHolder>() {
    private val items = mutableListOf<ChatMessage>()

    companion object {
        private const val VIEW_TYPE_USER = 1
        private const val VIEW_TYPE_ASSISTANT = 2
    }

    fun submitList(messages: List<ChatMessage>) {
        items.clear()
        items.addAll(messages)
        notifyDataSetChanged()
    }

    fun setStreamingText(text: String?) {
        // Find the last assistant message or add one
        if (text != null) {
            val lastIndex = items.size - 1
            if (lastIndex >= 0 && !items[lastIndex].isUser) {
                items[lastIndex] = items[lastIndex].copy(text = text, isStreaming = true)
                notifyItemChanged(lastIndex)
            } else {
                items.add(ChatMessage(text = text, isUser = false, isStreaming = true))
                notifyItemInserted(items.size - 1)
            }
        } else {
            // Streaming done — mark last assistant item as not streaming
            val lastIndex = items.size - 1
            if (lastIndex >= 0 && items[lastIndex].isStreaming) {
                items[lastIndex] = items[lastIndex].copy(isStreaming = false)
                notifyItemChanged(lastIndex)
            }
        }
    }

    override fun getItemViewType(position: Int): Int {
        return if (items[position].isUser) VIEW_TYPE_USER else VIEW_TYPE_ASSISTANT
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecyclerView.ViewHolder {
        return if (viewType == VIEW_TYPE_USER) {
            val binding = ItemCompanionMessageUserBinding.inflate(
                LayoutInflater.from(parent.context), parent, false
            )
            UserViewHolder(binding)
        } else {
            val binding = ItemCompanionMessageAssistantBinding.inflate(
                LayoutInflater.from(parent.context), parent, false
            )
            AssistantViewHolder(binding)
        }
    }

    override fun onBindViewHolder(holder: RecyclerView.ViewHolder, position: Int) {
        val message = items[position]
        when (holder) {
            is UserViewHolder -> holder.bind(message)
            is AssistantViewHolder -> holder.bind(message)
        }
    }

    override fun getItemCount(): Int = items.size

    class UserViewHolder(private val binding: ItemCompanionMessageUserBinding) :
        RecyclerView.ViewHolder(binding.root) {
        fun bind(message: ChatMessage) {
            binding.messageText.text = message.text
        }
    }

    class AssistantViewHolder(private val binding: ItemCompanionMessageAssistantBinding) :
        RecyclerView.ViewHolder(binding.root) {
        fun bind(message: ChatMessage) {
            binding.messageText.text = message.text
            binding.streamingIndicator.visibility = if (message.isStreaming) {
                android.view.View.VISIBLE
            } else {
                android.view.View.GONE
            }
        }
    }
}
