class CompanionFragment : Fragment(R.layout.fragment_companion) {
    private val viewModel: CompanionViewModel by viewModels()
    private var binding: FragmentCompanionBinding? = null
    private lateinit var adapter: CompanionAdapter

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        val fragmentBinding = FragmentCompanionBinding.bind(view)
        binding = fragmentBinding

        adapter = CompanionAdapter()
        fragmentBinding.companionMessages.apply {
            adapter = this@CompanionFragment.adapter
            layoutManager = LinearLayoutManager(requireContext()).apply {
                stackFromEnd = true
            }
        }

        // Observe messages
        viewModel.messages.observe(viewLifecycleOwner) { messages ->
            adapter.submitList(messages)
            // Scroll to bottom
            fragmentBinding.companionMessages.post {
                val lastIndex = adapter.itemCount - 1
                if (lastIndex >= 0) {
                    fragmentBinding.companionMessages.smoothScrollToPosition(lastIndex)
                }
            }
        }

        // Observe streaming text updates
        viewModel.currentStreamingText.observe(viewLifecycleOwner) { text ->
            adapter.setStreamingText(text)
            fragmentBinding.companionMessages.post {
                val lastIndex = adapter.itemCount - 1
                if (lastIndex >= 0) {
                    fragmentBinding.companionMessages.smoothScrollToPosition(lastIndex)
                }
            }
        }

        // Observe loading state
        viewModel.isLoading.observe(viewLifecycleOwner) { loading ->
            fragmentBinding.sendButton.isEnabled = !loading
            fragmentBinding.messageInput.isEnabled = !loading
            if (loading) {
                fragmentBinding.loadingIndicator.visibility = View.VISIBLE
            } else {
                fragmentBinding.loadingIndicator.visibility = View.GONE
            }
        }

        // Observe errors
        viewModel.error.observe(viewLifecycleOwner) { error ->
            if (error != null) {
                fragmentBinding.errorBanner.text = error
                fragmentBinding.errorBanner.visibility = View.VISIBLE
            } else {
                fragmentBinding.errorBanner.visibility = View.GONE
